"use client";

import { motion } from "framer-motion";
import { SECTIONS } from "@/lib/sections";

interface Props {
  activeIndex: number;
  onSelect: (index: number) => void;
}

export default function SideNav({ activeIndex, onSelect }: Props) {
  const progress = activeIndex / (SECTIONS.length - 1);

  return (
    <nav
      aria-label="Section navigation"
      className="fixed top-0 right-2 z-50 flex h-dvh py-20 md:right-5"
    >
      <div className="relative flex flex-col items-center justify-between">
        {/* Track line */}
        <div
          aria-hidden
          className="absolute inset-y-4 left-1/2 w-px -translate-x-1/2 bg-card-border md:inset-y-5"
        >
          {/* Progress fill */}
          <motion.div
            className="h-full w-full origin-top bg-linear-to-b from-primary to-secondary"
            animate={{ scaleY: progress }}
            transition={{ duration: 0.8, ease: [0.76, 0, 0.24, 1] }}
          />
        </div>

        {SECTIONS.map((section, i) => {
          const Icon = section.icon;
          const active = i === activeIndex;

          return (
            <button
              key={section.id}
              onClick={() => onSelect(i)}
              aria-label={`Go to ${section.label}`}
              aria-current={active ? "true" : undefined}
              className={`group relative flex size-8 items-center justify-center rounded-full border transition-colors md:size-10 ${
                active
                  ? "border-transparent text-white"
                  : "border-card-border bg-background text-muted hover:text-foreground"
              }`}
            >
              {active && (
                <motion.span
                  layoutId="nav-active-pill"
                  className="absolute inset-0 rounded-full bg-linear-to-br from-primary to-primary-2 shadow-[0_0_24px_var(--primary)]"
                  transition={{ type: "spring", stiffness: 380, damping: 30 }}
                />
              )}

              <span className="relative z-10">
                <Icon className="hidden size-4 md:block" />
                <span className="block size-1.5 rounded-full bg-current md:hidden" />
              </span>

              {/* Hover label (desktop only) */}
              <span className="glass pointer-events-none absolute right-full mr-3 hidden translate-x-2 rounded-lg px-3 py-1.5 text-xs font-medium whitespace-nowrap text-foreground opacity-0 transition duration-200 group-hover:translate-x-0 group-hover:opacity-100 group-focus-visible:translate-x-0 group-focus-visible:opacity-100 md:block">
                {section.label}
              </span>
            </button>
          );
        })}
      </div>
    </nav>
  );
}